-- Esquema de PostgreSQL (Neon). Es idempotente: se puede ejecutar varias veces.
-- La API también lo crea sola con EnsureCreated; este script sirve para crearlo a mano
-- y lo usa la herramienta de traspaso (api/tools/Frontenis.DataMigration).
-- Los nombres van entre comillas porque Entity Framework usa mayúsculas y minúsculas.

CREATE TABLE IF NOT EXISTS "Players" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(100) NOT NULL,
    "Position" smallint NOT NULL,            -- 1 = Delantero, 2 = Zaguero
    "GroupNumber" integer NULL               -- grupo de jugadores (1, 2, 3…) para seleccionarlos juntos
);

CREATE TABLE IF NOT EXISTS "Pairs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Player1Id" integer NOT NULL REFERENCES "Players"("Id"),
    "Player2Id" integer NOT NULL REFERENCES "Players"("Id"),
    CONSTRAINT "CK_Pairs_Distinct" CHECK ("Player1Id" <> "Player2Id")
);

CREATE TABLE IF NOT EXISTS "Competitions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(150) NOT NULL,
    "Type" smallint NOT NULL,                -- 1 = Liga, 2 = Torneo, 3 = Liga rotatoria
    "Status" smallint NOT NULL,              -- 1 Borrador, 2 Grupos, 3 Fase final, 4 Finalizada
    "PairCount" integer NOT NULL,
    "GroupCount" integer NOT NULL,
    "PairsPerGroup" integer NOT NULL,
    "PointsPerWin" integer NOT NULL,
    "PointsPerLoss" integer NOT NULL,
    "DoubleRound" boolean NOT NULL,
    "QualifiersPerGroup" integer NOT NULL,
    "Rounds" integer NOT NULL DEFAULT 0,       -- solo liga rotatoria
    "SetsPerMatch" integer NOT NULL DEFAULT 1, -- 1 o 2 sets por partido (con 2, un 3.º de desempate)
    "NextCompetitionId" integer NULL,          -- liga siguiente (ascensos/descensos)
    "CreatedAtUtc" timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS "Groups" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CompetitionId" integer NOT NULL REFERENCES "Competitions"("Id") ON DELETE CASCADE,
    "Name" varchar(50) NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_Groups_CompetitionId" ON "Groups"("CompetitionId");

CREATE TABLE IF NOT EXISTS "CompetitionEntries" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CompetitionId" integer NOT NULL REFERENCES "Competitions"("Id") ON DELETE CASCADE,
    "PairId" integer NOT NULL REFERENCES "Pairs"("Id"),
    "GroupId" integer NULL REFERENCES "Groups"("Id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_CompetitionEntries_CompetitionId_PairId" ON "CompetitionEntries"("CompetitionId", "PairId");

CREATE TABLE IF NOT EXISTS "Matches" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CompetitionId" integer NOT NULL REFERENCES "Competitions"("Id") ON DELETE CASCADE,
    "Phase" smallint NOT NULL,               -- 1 = Grupos, 2 = Fase final
    "GroupId" integer NULL REFERENCES "Groups"("Id"),
    "Round" integer NOT NULL,
    "Order" integer NOT NULL,
    "HomeEntryId" integer NULL REFERENCES "CompetitionEntries"("Id"),
    "AwayEntryId" integer NULL REFERENCES "CompetitionEntries"("Id"),
    "HomeScore" integer NULL,
    "AwayScore" integer NULL,
    "NextMatchId" integer NULL REFERENCES "Matches"("Id"),
    "NextSlot" smallint NULL,                -- 1 = Local, 2 = Visitante
    -- Tantos totales (suma de sets) pueden empatar; el ganador se decide por sets.
    "Set1Home" integer NULL, "Set1Away" integer NULL,
    "Set2Home" integer NULL, "Set2Away" integer NULL,
    "Set3Home" integer NULL, "Set3Away" integer NULL
);
CREATE INDEX IF NOT EXISTS "IX_Matches_CompetitionId_Phase_GroupId_Round" ON "Matches"("CompetitionId", "Phase", "GroupId", "Round");

CREATE TABLE IF NOT EXISTS "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Username" varchar(60) NOT NULL,
    "PasswordHash" varchar(300) NOT NULL,
    "Role" varchar(30) NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Users_Username" ON "Users"("Username");

-- Entrenamientos: partidos sueltos "a X tantos" con parejas libres
CREATE TABLE IF NOT EXISTS "TrainingSessions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(150) NOT NULL,
    "SessionDate" timestamptz NOT NULL,
    "PointsPerWin" integer NOT NULL,
    "PointsPerLoss" integer NOT NULL,
    "CreatedAtUtc" timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS "TrainingMatches" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SessionId" integer NOT NULL REFERENCES "TrainingSessions"("Id") ON DELETE CASCADE,
    "Order" integer NOT NULL,
    "Home1Id" integer NOT NULL REFERENCES "Players"("Id"),
    "Home2Id" integer NOT NULL REFERENCES "Players"("Id"),
    "Away1Id" integer NOT NULL REFERENCES "Players"("Id"),
    "Away2Id" integer NOT NULL REFERENCES "Players"("Id"),
    "HomeScore" integer NOT NULL,
    "AwayScore" integer NOT NULL,
    "PlayedAtUtc" timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_TrainingMatches_SessionId_Order" ON "TrainingMatches"("SessionId", "Order");

-- Reservas de entrenamientos: plantillas semanales, franjas por fecha y apuntados.
-- Fechas, horas y apertura son hora local de Madrid (sin conversión de zona horaria).
CREATE TABLE IF NOT EXISTS "SlotTemplates" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Day" smallint NOT NULL,                 -- 0 = domingo, 1 = lunes … 6 = sábado (DayOfWeek de .NET)
    "Start" time NOT NULL,
    "End" time NOT NULL,
    "Active" boolean NOT NULL
);

CREATE TABLE IF NOT EXISTS "TrainingSlots" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Date" date NOT NULL,
    "Start" time NOT NULL,
    "End" time NOT NULL,
    "OpensAt" timestamptz NOT NULL,          -- hora local de Madrid a partir de la cual se puede apuntar
    "IsCancelled" boolean NOT NULL,
    "TemplateId" integer NULL REFERENCES "SlotTemplates"("Id") ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS "IX_TrainingSlots_Date_Start" ON "TrainingSlots"("Date", "Start");
CREATE INDEX IF NOT EXISTS "IX_TrainingSlots_TemplateId" ON "TrainingSlots"("TemplateId");

CREATE TABLE IF NOT EXISTS "SlotAttendances" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SlotId" integer NOT NULL REFERENCES "TrainingSlots"("Id") ON DELETE CASCADE,
    "PlayerId" integer NOT NULL REFERENCES "Players"("Id") ON DELETE CASCADE,
    "RegisteredAtUtc" timestamptz NOT NULL,
    "RegisteredByPlayerId" integer NULL REFERENCES "Players"("Id") ON DELETE SET NULL   -- titular que apuntó; NULL = administrador
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_SlotAttendances_SlotId_PlayerId" ON "SlotAttendances"("SlotId", "PlayerId");
CREATE INDEX IF NOT EXISTS "IX_SlotAttendances_PlayerId" ON "SlotAttendances"("PlayerId");
ALTER TABLE "SlotAttendances" ADD COLUMN IF NOT EXISTS "RegisteredByPlayerId" integer NULL REFERENCES "Players"("Id") ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS "IX_SlotAttendances_RegisteredByPlayerId" ON "SlotAttendances"("RegisteredByPlayerId");

-- Apuntarse sin usuario: cada dispositivo guarda un identificador aleatorio (aquí solo su SHA-256) vinculado a su jugador.
CREATE TABLE IF NOT EXISTS "DeviceLinks" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DeviceHash" varchar(64) NOT NULL,
    "PlayerId" integer NOT NULL REFERENCES "Players"("Id") ON DELETE CASCADE,
    "LinkedAtUtc" timestamptz NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_DeviceLinks_DeviceHash" ON "DeviceLinks"("DeviceHash");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_DeviceLinks_PlayerId" ON "DeviceLinks"("PlayerId");

-- Apadrinados: el jugador titular puede apuntar también a estos jugadores desde su dispositivo.
CREATE TABLE IF NOT EXISTS "PlayerDelegates" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OwnerPlayerId" integer NOT NULL REFERENCES "Players"("Id") ON DELETE CASCADE,
    "DelegatePlayerId" integer NOT NULL REFERENCES "Players"("Id") ON DELETE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_PlayerDelegates_OwnerPlayerId_DelegatePlayerId" ON "PlayerDelegates"("OwnerPlayerId", "DelegatePlayerId");
CREATE INDEX IF NOT EXISTS "IX_PlayerDelegates_DelegatePlayerId" ON "PlayerDelegates"("DelegatePlayerId");

-- Resultados enviados por jugadores desde su dispositivo, pendientes de aprobación del administrador.
CREATE TABLE IF NOT EXISTS "MatchSubmissions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "MatchId" integer NOT NULL REFERENCES "Matches"("Id") ON DELETE CASCADE,
    "PlayerId" integer NOT NULL REFERENCES "Players"("Id") ON DELETE CASCADE,
    "SubmittedAtUtc" timestamptz NOT NULL,
    "Set1Home" integer NOT NULL, "Set1Away" integer NOT NULL,
    "Set2Home" integer NULL, "Set2Away" integer NULL,
    "Set3Home" integer NULL, "Set3Away" integer NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_MatchSubmissions_MatchId" ON "MatchSubmissions"("MatchId");
CREATE INDEX IF NOT EXISTS "IX_MatchSubmissions_PlayerId" ON "MatchSubmissions"("PlayerId");

-- Copia de los resultados enviados que el administrador rechazó, por si se rechazaron sin querer (sin claves foráneas).
CREATE TABLE IF NOT EXISTS "RejectedSubmissions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "MatchId" integer NOT NULL,
    "CompetitionId" integer NOT NULL,
    "PlayerId" integer NOT NULL,
    "SubmittedAtUtc" timestamptz NOT NULL,
    "RejectedAtUtc" timestamptz NOT NULL,
    "Set1Home" integer NOT NULL, "Set1Away" integer NOT NULL,
    "Set2Home" integer NULL, "Set2Away" integer NULL,
    "Set3Home" integer NULL, "Set3Away" integer NULL
);
CREATE INDEX IF NOT EXISTS "IX_RejectedSubmissions_CompetitionId" ON "RejectedSubmissions"("CompetitionId");

-- Registro de actividad: acciones que modifican datos (POST, PUT, DELETE). La API borra las de más de 30 días.
CREATE TABLE IF NOT EXISTS "AuditLogs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "AtUtc" timestamptz NOT NULL,
    "Actor" smallint NOT NULL,              -- 0 visitante, 1 jugador, 2 administrador
    "ActorName" varchar(100) NOT NULL,
    "PlayerId" integer NULL,
    "Method" varchar(10) NOT NULL,
    "Path" varchar(300) NOT NULL,
    "Status" integer NOT NULL,
    "DurationMs" integer NOT NULL,
    "Device" varchar(120) NULL               -- navegador, sistema y huella corta al vincular/desvincular un móvil
);
CREATE INDEX IF NOT EXISTS "IX_AuditLogs_AtUtc" ON "AuditLogs"("AtUtc");
